const UTM = (function(){
  let u = '';
  try {
    const q = new URLSearchParams(location.search);
    const parts = ['utm_source','utm_medium','utm_campaign'].map(k => q.get(k)).filter(Boolean);
    if (!parts.length && q.has('fbclid')) parts.push('facebook');
    if (!parts.length && q.has('gclid')) parts.push('google');
    if (parts.length) sessionStorage.setItem('rafiq-utm', parts.join('/'));
    u = sessionStorage.getItem('rafiq-utm') || '';
    if (!sessionStorage.getItem('rafiq-ref') && document.referrer && new URL(document.referrer).host !== location.host) sessionStorage.setItem('rafiq-ref', new URL(document.referrer).hostname);
  } catch (e) {}
  return u;
})();
