const MORE = {"whatsapp-booking":{"sub":"بيرد على عملاءك على واتساب، يحجز لهم المواعيد، ويبعت التذكير لوحده","problem":"لو رسايل واتساب عندك بتتأخر في الرد، أو بتوصلك رسايل بعد ما تقفل، أو فيه عملاء بيحجزوا وما بييجوا. في الحالات دي العميل غالبًا بيحجز عند غيرك.","steps":["العميل يبعت رسالة على واتساب في أي وقت، حتى آخر الليل","المساعد يرد عليه فورًا، ويجاوب أسئلته من معلومات شغلك إنت","يعرض عليه المواعيد المتاحة من التقويم، ويحجز له الموعد اللي يختاره","يبعت له تذكير قبل الموعد بيوم وبساعة، ولو حب يغيّر الموعد يغيّره له"],"plain":["مساعد ذكي شغّال على رقم واتساب الخاص بشغلك، زي موظف استقبال موجود 24 ساعة. أي عميل يبعت رسالة، يرد عليه خلال ثواني: يقول له الأسعار ومواعيد العمل من المعلومات اللي أخدها منك، وبعدها يحجز له الموعد بنفسه.","يعني مش لازم تمسك الموبايل طول اليوم. الحجوزات بتتسجّل لوحدها في تقويم جوجل، والعميل بيوصله تذكير قبل موعده. ولو حد سأل سؤال المساعد ما يعرف إجابته، بيحوّل المحادثة لموظف من عندك."],"story":"عيادة بتقفل بالليل. الساعة 11:52 عميلة تبعت: «حابة أحجز موعد بكرة». المساعد يرد خلال ثواني ويعرض عليها موعدين متاحين، هي تختار 6:30، والحجز بيتسجّل. من غير المساعد، الرسالة كانت هتستنى للصبح، وممكن العميلة تكون حجزت عند عيادة تانية.","gains":[["ما في عميل بيضيع بسبب تأخير الرد","اللي يبعت لك الساعة 2 بعد نص الليل بياخد رد وحجز فورًا، بدل ما يحجز عند غيرك."],["العميل ما بينسى موعده","بيوصله تذكير قبل الموعد بيوم وبساعة. ولو حب يغيّر الموعد، بيغيّره من نفس المحادثة."],["فريقك يركّز مع العملاء اللي قدامه","الأسئلة المتكررة المساعد بيرد عليها، والسؤال الصعب بس هو اللي بيوصل لموظفك."],["كل الحجوزات في مكان واحد","كل حجز بيتسجّل في تقويم جوجل، فتعرف يومك فيه إيه من أول نظرة."]],"qa":[["العميل هيعرف إنه بيكلم برنامج؟","المساعد بيرد بأسلوب طبيعي وبنفس لهجة العميل. ولو العميل سأله، بيقول إنه المساعد الذكي. والعميل يقدر يطلب موظف في أي وقت."],["ولو سأل عن شيء المساعد ما يعرفه؟","ما بيخترع إجابة من عنده. بيحوّل المحادثة لموظف، وبيوصلك تنبيه فورًا."],["لازم أجيب رقم جديد؟","محتاجين رقم موبايل مش مفعّل عليه واتساب العادي، عشان نربطه بواتساب للأعمال الرسمي."],["التكلفة الشهرية بتتحسب إزاي؟","حوالي 150 – 300 ج.م لكل 1,000 رسالة، يعني على قد استخدامك."],["إيه اللي يميزها عن باقي خدماتنا؟","هي الخدمة الوحيدة عندنا اللي بتحجز الموعد في التقويم من داخل محادثة واتساب. لو عملاءك بيسألوا في تعليقات فيسبوك وإنستجرام، شوف «الرد التلقائي على التعليقات». ولو بيسألوا في موقعك، شوف «مساعد ذكي على موقعك»."]]},"comment-reply":{"sub":"أي حد يسأل عن السعر في تعليقات فيسبوك وإنستجرام، بيوصله الرد في الخاص فورًا","problem":"لو بتبيع من صفحتك، وتعليقات «بكام؟» بتبقى ساعات من غير رد. العميل وقتها بيملّ ويشتري من صفحة تانية.","steps":["حد يكتب تعليق فيه «بكام» أو «السعر» أو «تفاصيل»","الصفحة ترد على تعليقه فورًا","توصله رسالة في الخاص فيها السعر والصور ورابط الطلب","الأسئلة غير المعتادة بتتحوّل لك إنت ترد عليها"],"plain":["نظام بيتابع التعليقات على صفحتك. أي حد يكتب «بكام؟» تحت البوست، بياخد رد على تعليقه خلال ثواني، وتوصله رسالة في الخاص فيها السعر والصور ورابط الطلب.","كل ده بيحصل لوحده وإنت نايم أو مشغول. إنت اللي بتختار الكلمات اللي النظام يرد عليها، ونص الرد بيتكتب بالطريقة اللي تحبها. والتعليق اللي فيه شكوى أو سؤال غير معتاد ما بيرد عليه لوحده، بيحوّله لك ترد بنفسك."],"story":"صفحة بتبيع شنط جلد نشرت بوست جديد، وسارة علّقت: «بكام؟ وفيه ألوان إيه؟». بعد ثواني الصفحة ترد على تعليقها، وتوصلها رسالة في الخاص فيها السعر والألوان المتوفرة ورابط الطلب. سارة لسه متحمسة، فتطلب وهي في مكانها.","gains":[["العميل بيشتري وهو لسه متحمس","السعر بيوصله بعد ثواني من سؤاله، قبل ما يملّ ويروح لصفحة تانية."],["ما في تعليق بيتنسى","شغّال على البوستات العادية وعلى الإعلانات، مهما زاد عدد التعليقات."],["المهم بس هو اللي بيوصلك","الأسئلة غير المعتادة والشكاوى ما بيرد عليها لوحده، بيحوّلها لك ترد بنفسك."],["الصفحة بتتكلم بأسلوبك","إنت اللي بتختار الكلمات اللي يرد عليها، ونص الرد اللي بيتبعت."]],"qa":[["بيرد على كل التعليقات؟","بيرد على الكلمات اللي إنت بتختارها، زي: بكام، السعر، تفاصيل. والنص اللي بيتبعت إنت اللي بتكتبه، أو بنكتبه معاك."],["إيه المطلوب مني بعد التشغيل؟","تحدّث الأسعار والصور لما تتغير، وبس. الباقي شغّال لوحده."],["شغّال على إنستجرام كمان؟","أيوه، على صفحة فيسبوك وحساب إنستجرام. بس لازم حساب إنستجرام يكون تجاري ومربوط بالصفحة."],["محتاجين مني إيه عشان نبدأ؟","إذن دخول كمشرف على الصفحة، والأسعار وصور المنتجات."],["إيه اللي يميزها عن باقي خدماتنا؟","هي الخدمة الوحيدة عندنا اللي بتشتغل على التعليقات نفسها: بترد على التعليق وتكمّل مع العميل في الخاص. «مساعد واتساب للرد والحجز» بيرد على اللي يبعت لك على واتساب، و«مساعد ذكي على موقعك» بيرد على زوار الموقع."]]},"site-assistant":{"sub":"عارف منتجاتك وأسعارك، بيرد على زوار موقعك، وبيجمع لك بيانات المهتمين","problem":"لو عندك موقع، وزواره عندهم أسئلة وما بيلاقوا حد يرد عليهم، فبيقفلوا الصفحة ويمشوا من غير ما يكلموك.","steps":["بنجمع معلوماتك: الخدمات والأسعار والسياسات","المساعد بيتعلّم منها","يرد على الزوار، ويقترح على كل واحد الأنسب له","ياخد اسم ورقم المهتم ويبعتهم لك"],"plain":["نافذة محادثة صغيرة في موقعك، وراها مساعد ذكي عارف خدماتك وأسعارك. الزائر يكتب سؤاله، والمساعد يرد عليه فورًا ويقترح عليه الأنسب له.","ولما الزائر يهتم، المساعد ياخد اسمه ورقمه ويبعتهم لك، فتكلمه وإنت عارف هو محتاج إيه. وكمان بيوصلك تقرير بأكتر الأسئلة اللي الزوار بيسألوها، فتعرف موقعك ناقصه إيه."],"story":"واحد دخل موقع شركة خدمات الساعة 1 بعد نص الليل، وحابب يعرف السعر. بدل ما يدوّر في الصفحات ويقفل الموقع، يكتب سؤاله في نافذة المحادثة وياخد الرد. المساعد ياخد اسمه ورقمه، والصبح الفريق يلاقي بياناته جاهزة ويكلمه.","gains":[["الزائر بيلاقي إجابة قبل ما يمشي","بدل ما يدوّر في الصفحات ويقفل الموقع، بيسأل وياخد الرد فورًا."],["بيانات المهتمين بتوصلك جاهزة","اسم ورقم وطلب كل زائر مهتم، فتتصل به وإنت عارف هو محتاج إيه."],["بتعرف الناس بتسأل عن إيه","تقرير بأكتر الأسئلة تكرارًا، فتعرف موقعك وعروضك ناقصهم إيه."],["ما بيجاوب من عنده","بيجاوب من ملفاتك إنت بس. والسؤال اللي إجابته مش موجودة فيها بيحوّله لفريقك."]],"qa":[["بيعرف الإجابات إزاي؟","من ملفات الخدمات والأسعار اللي بتبعتها لنا. والسؤال اللي إجابته مش فيها ما بيخترع له إجابة، بيحوّله لفريقك."],["بيشتغل على موقعي الحالي؟","أيوه. نافذة المحادثة بتتركّب على أي موقع."],["أقدر أجرّبه قبل ما أطلبه؟","أيوه. المساعد الموجود في موقعنا ده هو نفس الخدمة. جرّبه واسأله عن أي شيء."],["محتاجين مني إيه؟","ملفات الخدمات والأسعار، وإذن نركّب النافذة على موقعك."],["إيه اللي يميزها عن باقي خدماتنا؟","ده بيتركّب على موقع موجود عندك. لو ما عندك موقع، خدمة «موقع شركة مع مساعد ذكي» بتبني لك الموقع والمساعد مع بعض. ولو عملاءك بيكلموك على واتساب مش على الموقع، شوف «مساعد واتساب للرد والحجز»."]]},"cod-confirm":{"sub":"العميل بيأكد طلبه بضغطة قبل الشحن، والطلب الوهمي بيتلغي","problem":"لو بتبيع بالدفع عند الاستلام وفيه طلبات كتير بترجع. من 25 لـ 30% من طلبات الدفع عند الاستلام بتترفض أو ما بتكمل، وإنت اللي بتدفع الشحن ذهاب ورجوع.","steps":["طلب جديد يوصل من المتجر أو من جدول الطلبات","رسالة واتساب تتبعت للعميل فيها تفاصيل الطلب","العميل يأكد أو يلغي بضغطة زر","حالة الطلب تتحدّث لوحدها، واللي ما رد يوصله تذكير بعد ساعات قليلة"],"plain":["قبل ما تشحن أي طلب، النظام بيبعت للعميل رسالة واتساب فيها تفاصيل طلبه وزرّين: تأكيد أو إلغاء. الطلب اللي صاحبه ما أكده ما بيخرج من المخزن.","بالشكل ده بتشحن للعملاء الجادين بس. مش محتاج موظف يتصل بكل عميل، وحالة كل طلب بتتحدّث لوحدها، وكل يوم بيوصلك تقرير بالطلبات."],"story":"متجر ملابس وصله طلب من أحمد: قميص قطن × 2 بـ 650 جنيه. قبل الشحن، أحمد وصلته رسالة واتساب فيها تفاصيل الطلب وزرّين. ضغط «تأكيد»، فالطلب خرج للشحن. لو كان ضغط «إلغاء» أو ما رد، الطلب كان هيبقى في المخزن، والمتجر ما يدفع شحن من غير فايدة.","gains":[["ما تدفع شحن لطلب وهمي","الطلب غير الجاد بيتلغي قبل الشحن، فما تدفع تكلفة الشحن ذهاب ورجوع."],["من غير مكالمات تأكيد","بدل ما موظف يتصل بكل عميل، العميل بيأكد بضغطة واحدة."],["عارف حالة كل طلب","حالة الطلب بتتحدّث لوحدها، واللي ما رد بيوصله تذكير، وإنت بيوصلك تقرير يومي."],["شغّال مع متجرك زي ما هو","بيتربط بـ Shopify وEasyOrders وWooCommerce، أو بجدول الطلبات لو بتسجّل فيه."]],"qa":[["ولو العميل ما رد؟","بيوصله تذكير بعد ساعات قليلة. والطلب بيبقى غير مؤكد لحد ما يرد، فما بيتشحن."],["بيشتغل مع متجري؟","بيتربط بـ Shopify وEasyOrders وWooCommerce. ولو بتسجّل الطلبات في جدول، بيتربط بالجدول."],["كم التكلفة الشهرية؟","حوالي 200 – 400 ج.م لكل 1,000 طلب."],["محتاجين مني إيه؟","رقم واتساب للأعمال، وإذن دخول على المتجر أو جدول الطلبات."],["إيه اللي يميزها عن باقي خدماتنا؟","دي بتشتغل بعد ما العميل يطلب فعلًا، عشان تتأكد إنه جاد قبل الشحن. أما «استرجاع السلات المتروكة» فبتشتغل قبل الطلب، مع اللي حط المنتج في السلة وما كمّل."]]},"cart-recovery":{"sub":"رسالة لكل عميل ترك السلة في متجرك، ومعاها رابط يكمّل منه الطلب","problem":"لو عندك متجر إلكتروني، والعملاء بيحطوا المنتجات في السلة وبعدها يخرجوا من غير ما يدفعوا. دي مبيعات كانت شبه مضمونة وضاعت في آخر خطوة.","steps":["العميل يترك السلة من غير ما يدفع","بعد ساعة توصله رسالة فيها المنتج ورابط يكمّل منه الطلب","لو ما رجع، توصله رسالة تانية بعد يوم (ومعاها خصم صغير لو حبيت)","بيوصلك تقرير بالمبيعات اللي رجعت"],"plain":["«السلة المتروكة» يعني: عميل اختار منتج ووصل لصفحة الدفع، وبعدها خرج من غير ما يشتري. ده عميل كان باقي له خطوة واحدة ويشتري.","النظام بيبعت له رسالة واتساب بعد ساعة تفكّره باللي اختاره، ومعاها رابط يكمّل منه مباشرة. ولو ما رجع، توصله رسالة تانية بعد يوم، وممكن تحط فيها خصم صغير لو حبيت. وبيوصلك تقرير بالمبيعات اللي رجعت بسبب الرسايل."],"story":"نورة حطّت عطر في السلة في متجر عطور، وانشغلت فقفلت الصفحة. بعد ساعة وصلتها رسالة واتساب تفكّرها بالعطر ومعاها رابط. دخلت منه وكمّلت الدفع. من غير الرسالة، كانت غالبًا هتنسى.","gains":[["مبيعات كانت هتضيع","ده عميل كان باقي له خطوة ويشتري، ورسالة واحدة في وقتها ممكن ترجّعه."],["من غير أي مجهود منك","الرسايل بتتبعت لوحدها في وقتها، وبتقف لوحدها لما العميل يشتري."],["عارف رجّعت كم","تقرير بالمبيعات اللي رجعت بسبب الرسايل."],["الخصم قرارك إنت","كود الخصم اختياري، وإنت اللي بتحدد قيمته أو تلغيه تمامًا."]],"qa":[["الخصم إجباري؟","لا. الخصم اختياري وفي الرسالة التانية بس، وإنت اللي بتحدد قيمته أو تلغيه."],["الرسايل هتضايق عملائي؟","رسالتين بس، وبيتبعتوا للعميل اللي وافق يستقبل رسايل من متجرك."],["بيشتغل مع أي متاجر؟","سلة وزد وShopify."],["كم التكلفة الشهرية؟","على حسب عدد الرسايل اللي بتتبعت."],["إيه اللي يميزها عن باقي خدماتنا؟","دي بتكلم اللي كان هيشتري وما كمّل. «تأكيد طلبات الدفع عند الاستلام» بتكلم اللي طلب فعلًا، و«عروض للعملاء القدامى» بتكلم اللي اشترى قبل ومضى عليه وقت."]]},"lead-followup":{"sub":"رسايل متابعة للي سأل وما اشترى، لحد ما ياخد قراره","problem":"لو عملاء كتير بيسألوا عن السعر وبعدها يسكتوا، وما حد من فريقك بيلحق يتابعهم، فبيشتروا من غيرك.","steps":["كل عميل سأل بيتسجّل لوحده","بعد يوم: رسالة متابعة خفيفة","بعد 3 أيام: معلومة أو عرض يساعده ياخد القرار","اللي يرد بيتحوّل لك ومعاه تنبيه"],"plain":["ناس كتير بتسأل عن السعر وبعدها تنشغل وتنسى. وأحيانًا كل اللي محتاجينه حد يفكّرهم.","النظام بيسجّل كل واحد سأل، وبعد يوم يبعت له رسالة خفيفة، وبعد 3 أيام معلومة أو عرض يساعده يقرر. الرسالة بتتكتب على حسب هو سأل عن إيه، مش رسالة واحدة للكل. واللي يرد بيتحوّل لك فورًا."],"story":"كريم سأل شركة عقارات عن شقة 3 غرف، قال السعر عالي وما رد بعدها. بعد يوم وصلته رسالة خفيفة تسأل عنه. وبعد 3 أيام وصلته معلومة عن التقسيط والمعاينة المجانية. كريم رد، والتنبيه وصل لفريق المبيعات عشان يكلموه.","gains":[["ما في عميل مهتم بيتنسى","كل واحد سأل بيتسجّل وبيتابَع لوحده، حتى لو فريقك مشغول."],["رسالة تخص كل عميل","بتتكتب على حسب هو سأل عن إيه، مش رسالة واحدة منسوخة للكل."],["وقتك للي رد فعلًا","بيوصلك تنبيه لما العميل يرد، فتكلم الجاهزين بس."],["عارف المتابعة ماشية إزاي","بيوصلك تقرير كل أسبوع."]],"qa":[["كم رسالة بتوصل العميل؟","من رسالتين لثلاثة، وبعدها المتابعة بتقف. من غير إلحاح."],["النظام بيوعد العميل بخصومات؟","لا. بيستخدم نصوص العروض اللي بتبعتها لنا وبس."],["العملاء بيتسجّلوا إزاي؟","من واتساب أو نموذج تسجيل أو الإعلانات، على حسب طريقة استقبالك للعملاء."],["مناسبة لأي نوع شغل؟","للمنتجات والخدمات اللي سعرها عالي والعميل بياخد وقت يفكر فيها: عقارات، سيارات، دورات."],["إيه اللي يميزها عن باقي خدماتنا؟","دي بتتابع اللي سأل ولسه ما اشترى، برسايل بتتبعت لوحدها. لو محتاج كمان تشوف كل عملاءك ومراحلهم في شاشة واحدة مع فريقك، شوف «نظام إدارة العملاء (CRM)»."]]},"crm":{"sub":"كل عملاءك ومراحلهم في مكان واحد، مع تذكير للفريق وتقرير كل أسبوع","problem":"لو عملاءك متوزعين بين واتساب والصفحة والورق، وما حد في الفريق عارف كل عميل وصل لأي مرحلة.","steps":["كل رسالة من واتساب أو الصفحة بتتحوّل لعميل مسجّل في النظام","كل عميل له مرحلة: مهتم، متابعة، اشترى","تذكير يومي للفريق بالعملاء اللي لازم يتابعوهم","تقرير أسبوعي بالمبيعات ومصادر العملاء"],"plain":["CRM يعني نظام لإدارة العملاء، زي دفتر عملاء ذكي. كل واحد كلّمك على واتساب أو الصفحة بيتسجّل فيه لوحده، ومعاه مرحلته: مهتم، متابعة، اشترى.","كل يوم الصبح النظام بيفكّر فريقك بالعملاء اللي لازم يكلموهم اليوم. وكل أسبوع بيوصلك تقرير بالمبيعات ومصادر العملاء، فتعرف تصرف ميزانية الإعلانات على إيه."],"story":"معرض سيارات بيوصله عملاء من فيسبوك وواتساب والإعلانات. خالد سأل عن سيارة موديل 2022، فتسجّل لوحده كعميل «مهتم» والفريق وصله تنبيه. تاني يوم الساعة 9 الصبح، الفريق وصلته رسالة فيها أسماء اللي لازم يتابعوهم اليوم، وخالد منهم.","gains":[["كل عملاءك في مكان واحد","بدل ما يتوزعوا بين واتساب والصفحة والورق، بتشوفهم في شاشة واحدة."],["ما في متابعة بتتنسى","تذكير يومي للفريق بأسماء اللي لازم يتابعوهم."],["عارف عملاءك جايين من فين","تقرير أسبوعي بالمبيعات ومصادر العملاء، فتعرف تصرف ميزانية الإعلان على إيه."],["كل واحد شايف اللي يخصه","كل عضو في الفريق بيشوف اللي مسموح له بس."]],"qa":[["عندي جدول عملاء قديم، أعمل به إيه؟","بنبدأ منه. ابعت لنا الجدول الحالي لو موجود، ونبني النظام عليه."],["كل الموظفين هيشوفوا كل شيء؟","لا. كل عضو في الفريق له صلاحيات خاصة، يعني بيشوف اللي يخصه بس."],["بيتربط بإيه؟","بواتساب والصفحة والمخزون."],["مناسب لشغلي؟","معمول للشركات اللي عندها فريق مبيعات، والمعارض، والعيادات الكبيرة. لو شغلك لسه صغير، ممكن تبدأ بخدمة أبسط زي «متابعة العملاء المهتمين»."],["إيه اللي يميزها عن باقي خدماتنا؟","ده نظام كامل لفريقك: شاشة فيها كل العملاء ومراحلهم، وتذكير يومي، وتقرير أسبوعي. «متابعة العملاء المهتمين» أبسط: بتسجّل المهتمين وتبعت لهم رسايل متابعة، من غير شاشة مراحل للفريق."]]},"win-back":{"sub":"رسايل خاصة ترجّع اللي اشترى منك قبل، عشان يشتري تاني","problem":"لو عندك مئات العملاء اشتروا منك قبل، وما حد بيكلمهم بعدها.","steps":["بنقسّم العملاء على حسب آخر مرة اشتروا","رسالة باسم العميل، وفيها عرض يناسب اللي اشتراه","بتتبعت لوحدها كل أسبوع أو كل شهر","اللي يرد بكلمة «إيقاف» بيتشال من القائمة فورًا"],"plain":["عندك عملاء اشتروا منك مرة وما رجعوا. هم عارفينك وجرّبوا منتجك، وكل اللي ناقصهم سبب يرجعوا.","النظام بيبعت لكل واحد منهم رسالة واتساب باسمه، فيها عرض يناسب اللي اشتراه قبل، كل أسبوع أو كل شهر. الرسايل بتتبعت بس للي وافق يستقبل عروض، واللي يكتب «إيقاف» بيتشال من القائمة فورًا."],"story":"منى اشترت جاكيت شتوي من متجر أزياء وما رجعت بعدها. اليوم وصلتها رسالة باسمها عن خصم 15% على تشكيلة الشتاء لحد يوم الأحد. دي مش إعلان عام للكل، دي رسالة مكتوبة على حسب اللي هي اشترته.","gains":[["بتبيع للي عارفك","هم جرّبوا منتجك قبل، وكل اللي ناقصهم سبب يرجعوا."],["رسالة شخصية لكل عميل","باسمه وباللي اشتراه، مش إعلان عام للكل."],["رقمك في أمان","بتتبعت بس للي وافق على العروض، واللي يرد بكلمة «إيقاف» بيتشال من القائمة فورًا."],["عارف مين رجع","تقرير باللي رجعوا واشتروا."]],"qa":[["ممكن رقمي يتحظر؟","بنستخدم نصوص رسايل وافقت عليها Meta (الشركة المالكة لواتساب)، وبنبعت بس للي وافق. ده اللي بيحمي الرقم."],["كم تكلفة الرسايل؟","حوالي 3,500 ج.م لكل 1,000 رسالة عرض في مصر، بتتدفع لواتساب وباسمك."],["الرسايل بتتبعت كل أسبوع ولا كل شهر؟","على حسب اختيارك: كل أسبوع أو كل شهر."],["محتاجين مني إيه؟","قائمة العملاء السابقين وموافقتهم على العروض، والعروض اللي حابب تقدمها."],["إيه اللي يميزها عن باقي خدماتنا؟","دي للعملاء اللي اشتروا منك فعلًا ومضى عليهم وقت. «متابعة العملاء المهتمين» للي سأل وما اشترى، و«استرجاع السلات المتروكة» للي ترك السلة قبل الدفع."]]},"product-photos":{"sub":"من صورة بالموبايل لصور احترافية بخلفيات ومشاهد مختلفة","problem":"لو محتاج صور قوية لمنتجاتك، والتصوير الاحترافي غالي وبياخد وقت، وصور الموبايل ما بتقنع العميل يشتري.","steps":["تبعت لنا صور واضحة للمنتج بالموبايل","بنحط المنتج في مشاهد احترافية بألوان علامتك","بنسلّمك من 20 لـ 50 صورة بمقاسات المنصات والمتجر","جولة تعديل مجانية"],"plain":["تبعت لنا صور منتجك بالموبايل، ونرجّعها لك صور احترافية: نفس المنتج، بس في مشاهد وخلفيات مختلفة بألوان علامتك، كأنها متصورة في استوديو.","مش محتاج تحجز استوديو ولا تجيب مصوّر ولا تنقل المنتجات. بتستلم من 20 لـ 50 صورة بمقاسات البوست والستوري والمتجر خلال 2 لـ 4 أيام، ومعاها جولة تعديل مجانية لو فيه شيء حابب تغيّره."],"story":"براند عطور عنده زجاجة عطر جديدة، وصاحبه صوّرها بالموبايل على الطاولة. بعد أيام قليلة بيستلم صور لنفس الزجاجة في مشاهد فخمة بالأسود والذهبي، جاهزة للبوستات والستوري وصفحة المنتج في المتجر.","gains":[["من غير استوديو ولا مصوّر","لا حجز ولا نقل منتجات ولا يوم تصوير. صور الموبايل كفاية."],["صور تكفي كل مكان","من 20 لـ 50 صورة بمقاسات البوست والستوري والمتجر."],["جاهزة في أيام","التسليم خلال 2 لـ 4 أيام، ومعاه جولة تعديل مجانية."],["بألوان علامتك","الخلفيات بتتعمل على ألوان وأسلوب علامتك."]],"qa":[["شكل منتجي هيتغير في الصور؟","اللي بيتغير الخلفية والمشهد والإضاءة، والمنتج بيبقى منتجك. ولو طلعت صورة مش شبهه، بنعدّلها في جولة التعديل."],["أبعت صور شكلها إيه؟","صور واضحة للمنتج من أكتر من زاوية، ومعاها ألوان وأسلوب علامتك."],["فيه تكلفة شهرية؟","لا، ما في."],["مناسبة لأي منتجات؟","ملابس، مجوهرات، مستحضرات تجميل، وأكل."],["إيه اللي يميزها عن باقي خدماتنا؟","دي بتسلّمك صور ثابتة للمنتج. لو محتاج فيديو قصير للإعلان، شوف «فيديو إعلاني بالذكاء الاصطناعي». ولو محتاج بوستات كاملة تتنشر كل شهر، شوف «محتوى شهري مجدول»."]]},"ad-video":{"sub":"فيديو قصير جاهز للإعلان، بمتحدث افتراضي أو مشاهد معمولة بالذكاء الاصطناعي","problem":"لو محتاج فيديو لإعلانك أو لمنتج جديد، والتصوير والمونتاج غاليين عليك. الفيديو بيبيع أكتر من الصورة.","steps":["بنكتب نص مدته من 15 لـ 30 ثانية","بنعمل المشاهد أو متحدث افتراضي","مونتاج مع كتابة على الشاشة وموسيقى","التسليم بمقاس الريلز والستوري"],"plain":["فيديو قصير من 15 لـ 30 ثانية جاهز تنشره كإعلان. إحنا بنكتب النص، وبنعمل المشاهد أو متحدث افتراضي بالذكاء الاصطناعي، وبنضيف الكتابة على الشاشة والموسيقى.","مش محتاج كاميرا ولا مكان تصوير ولا ممثلين ولا مونتاج. بتبعت لنا المنتج والعرض والشعار والألوان، وبتستلم الفيديو خلال 2 لـ 3 أيام بنسختين بمقاسين مختلفين."],"story":"متجر عنده عرض «خصم 10% لأول 100 طلب» وحابب يلحق ينشره كإعلان هذا الأسبوع. بدل ما يدوّر على مصوّر ومونتير، بيبعت المنتج والعرض، وبعد يومين أو ثلاثة بيستلم فيديو جاهز للريلز والستوري.","gains":[["من غير تصوير ولا ممثلين","لا كاميرا ولا مكان تصوير ولا مونتاج من ناحيتك."],["جاهز لكل المنصات","نسختين بمقاسين مختلفين، للريلز وللستوري."],["سريع ويلحق عرض الأسبوع","التسليم خلال 2 لـ 3 أيام، فتلحق به عرضك أو نزول منتجك الجديد."],["النص علينا","بنكتب نص الإعلان من معلومات منتجك وعرضك."]],"qa":[["يعني إيه متحدث افتراضي؟","شخصية معمولة بالذكاء الاصطناعي بتتكلم عن منتجك قدام الكاميرا، بدل ما تصوّر شخص حقيقي."],["أنا اللي هكتب نص الإعلان؟","لا. إحنا بنكتبه من معلومات منتجك وعرضك."],["كم مدة الفيديو؟","من 15 لـ 30 ثانية، ومعمول لإعلانات فيسبوك وتيك توك وسناب."],["فيه تكلفة شهرية؟","لا، ما في."],["إيه اللي يميزها عن باقي خدماتنا؟","دي بتسلّمك فيديو واحد قصير للإعلان. «صور منتجات بالذكاء الاصطناعي» بتسلّمك صور ثابتة، و«محتوى شهري مجدول» بيكتب ويصمم وينشر بوستات صفحتك كل شهر."]]},"content-autopilot":{"sub":"بوستات بتتكتب وتتصمم وتتنشر في وقتها، وإنت بس بتوافق","problem":"لو ما عندك وقت تكتب وتصمم كل يوم، فصفحتك واقفة والعملاء بينسوك.","steps":["خطة شهرية بالأفكار","البوستات بتتكتب وتتصمم","بتوصلك على واتساب عشان توافق أو تعدّل","بتتنشر لوحدها في وقتها"],"plain":["صفحتك بتنشر بانتظام من غير ما تكتب ولا تصمم. إحنا بنجهّز خطة الشهر، وبنكتب البوستات ونصممها.","كل بوست بيوصلك على واتساب أولًا: تقول «موافق» أو تطلب تعديل. بعدها بيتنشر لوحده في وقته. يعني ما في شيء بينزل على صفحتك من غير ما تشوفه."],"story":"صالون تجميل صاحبته مشغولة مع العميلات طول اليوم، والصفحة واقفة. مع الخدمة، بتوصلها بوستات الأسبوع على واتساب، تراجعها في دقيقة وتضغط «موافق»، والصفحة تبقى شغّالة طول الشهر.","gains":[["صفحة شغّالة طول الشهر","من 12 لـ 20 بوست بتصميماتهم، فالصفحة ما تقف والعملاء ما ينسوك."],["دقيقة واحدة منك","كل المطلوب إنك تضغط «موافق» على واتساب."],["ما في شيء بينزل من غير علمك","كل بوست بيمر عليك أولًا، وتعدّل اللي تحبه قبل النشر."],["الأفكار علينا","بنجهّز خطة الشهر من معلومات شغلك وعروضك."]],"qa":[["ليه السعر فيه جزء شهري؟","الجزء الأول للتجهيز وبيتدفع مرة واحدة. والجزء الشهري مقابل محتوى كل شهر: الخطة والكتابة والتصميم والنشر."],["محتاج أبعت لكم أفكار؟","لا. محتاجين معلومات شغلك وعروضك، والأفكار علينا."],["ولو بوست ما عجبني؟","بتكتب التعديل اللي تحبه على واتساب، والبوست بيتعدّل قبل ما يتنشر."],["محتاجين مني إيه؟","معلومات شغلك وعروضك، وإذن دخول على صفحاتك."],["إيه اللي يميزها عن باقي خدماتنا؟","دي الخدمة الوحيدة عندنا اللي سعرها فيه جزء شهري، لأنها بتجهّز محتوى جديد كل شهر وتنشره على صفحتك بنفسها. خدمات الصور والفيديو بتسلّمك المحتوى مرة واحدة."]]},"google-reviews":{"sub":"بيطلب التقييم من العملاء المبسوطين، وبيرد على كل تقييم","problem":"لو تقييماتك على جوجل قليلة، أو فيها تقييمات سلبية من غير رد. العميل المبسوط قليل لما يكتب تقييم، وغير الراضي دايمًا بيكتب. والتقييمات هي اللي بتخلّي الناس تختارك.","steps":["بعد الخدمة: رسالة تطلب من العميل يقيّمك","كل تقييم جديد بياخد رد مناسب","التقييم السلبي بيوصلك عنه تنبيه فورًا","تقرير شهري بالتقييمات"],"plain":["تقييمات جوجل هي النجوم اللي الناس بتشوفها جنب اسم شغلك في خرائط جوجل ونتائج البحث.","النظام بيبعت لكل عميل بعد الخدمة رسالة تطلب منه يقيّمك، وبيرد على كل تقييم جديد. ولو وصل تقييم سلبي، بيوصلك تنبيه فورًا عشان تتصرف قبل ما المشكلة تكبر."],"story":"عيادة أسنان، وهالة كتبت تقييم نجمتين: «استنيت ساعة كاملة بعد موعدي». التقييم بياخد رد مهذب، وصاحب العيادة بيوصله تنبيه فورًا، فيكلمها ويحل المشكلة.","gains":[["تقييمات أكتر من عملاء مبسوطين","العميل المبسوط غالبًا ما بيقيّم من نفسه. رسالة بسيطة بعد الخدمة بتفكّره."],["كل تقييم بياخد رد","الرد على التقييمات بيبيّن إن فيه حد مهتم وراء الشغل ده."],["بتعرف المشكلة فورًا","التقييم السلبي بيوصلك عنه تنبيه، فتكلم العميل قبل ما المشكلة تكبر."],["عارف وضع تقييماتك","تقرير شهري بالتقييمات."]],"qa":[["بتكتبوا تقييمات غير حقيقية؟","لا. النظام بيطلب التقييم من عملاءك الحقيقيين بس، بعد ما ياخدوا الخدمة."],["إيه اللي بيحصل لما يوصل تقييم سلبي؟","بيتكتب عليه رد مهذب، وبيوصلك تنبيه فورًا عشان تتصرف."],["كم التكلفة الشهرية؟","حوالي 20 – 100 ج.م."],["محتاجين مني إيه؟","إذن دخول على ملف شغلك في جوجل، وأرقام العملاء بعد الخدمة."],["إيه اللي يميزها عن باقي خدماتنا؟","دي الخدمة الوحيدة عندنا اللي شغلها على تقييماتك في جوجل: بتزوّدها وبترد عليها. باقي خدمات التسويق بتجهّز محتوى: صور وفيديو وبوستات."]]},"invoice-ai":{"sub":"صورة الفاتورة أو ملف PDF بيتحوّل لسطر مرتّب في ثواني","problem":"لو عندك موظف بيقعد ساعات ينقل الفواتير بيده للجدول أو لبرنامج المحاسبة، وأحيانًا بيغلط في رقم.","steps":["تصوّر الفاتورة، أو تبعت ملف PDF على واتساب أو الإيميل","النظام يقرا اسم المورّد والتاريخ والمبلغ والبنود","يضيفها سطر في الجدول أو برنامج المحاسبة","أي فاتورة مش واضحة بيحط عليها علامة للمراجعة"],"plain":["بدل ما الموظف ينقل كل فاتورة بيده، بيصوّرها أو يبعت ملف PDF على واتساب أو الإيميل. النظام بيقرا اسم المورّد (الجهة اللي اشتريت منها) والتاريخ والمبلغ والبنود، ويضيفهم سطر مرتّب في الجدول أو برنامج المحاسبة.","ولو الفاتورة مش واضحة، النظام ما بيخمّن الأرقام. بيحط عليها علامة عشان حد يراجعها بنفسه. وكل شهر بيوصلك تقرير بالمصروفات."],"story":"مكتب محاسبة بتوصله فواتير موردين كل يوم. المحاسب بيصوّر الفاتورة بالموبايل ويبعتها، وخلال ثواني بتتسجّل: المورّد، المبلغ، وعدد البنود. والفاتورة اللي صورتها مش واضحة بيتحط عليها علامة للمراجعة، وما بتتسجّل بأرقام غلط.","gains":[["ساعات النقل صارت ثواني","الفاتورة بتتسجّل أول ما صورتها تتبعت."],["أخطاء أقل","لا رقم بيتكتب غلط ولا فاتورة بتتنسى في الدرج."],["الفاتورة غير الواضحة ما بتمر","بيتحط عليها علامة للمراجعة، بدل ما تتسجّل بأرقام غلط."],["عارف مصروفاتك","تقرير شهري بالمصروفات."]],"qa":[["بيقرا الفواتير العربي؟","أيوه، بيقرا الصور وملفات PDF بالعربي والإنجليزي."],["البيانات بتتسجّل فين؟","في الجدول أو برنامج المحاسبة اللي إنت شغّال عليه، وبالأعمدة اللي إنت بتحددها."],["ولو الصورة مش واضحة؟","ما بتتسجّل. بيتحط عليها علامة عشان حد يراجعها."],["محتاجين مني إيه؟","نماذج من فواتيرك، والأعمدة اللي محتاجها في الجدول."],["إيه اللي يميزها عن باقي خدماتنا؟","دي خدمة لشغل الشركة الداخلي، مش للرد على العملاء ولا للتسويق: بتشيل عن فريقك نقل الفواتير. لو محتاج نظام كامل تدير منه شغلك اليومي، شوف «لوحة تحكم ونظام ويب داخلي»."]]},"landing-page":{"sub":"صفحة أو موقع سريع ومناسب للموبايل، مربوط بواتساب وبأداة قياس الإعلانات","problem":"لو بتعمل إعلانات، والإعلان بيودّي العميل لصفحة بطيئة، أو ما في صفحة أصلًا، فالعميل بيمشي.","steps":["بنفهم عرضك والعميل اللي حابب توصله","بنكتب المحتوى بالعربي ونصمم الصفحة","بنربطها بواتساب وبأداة قياس الإعلانات (بيكسل)","بننشرها على دومين باسمك، يعني عنوان خاص بك على الإنترنت"],"plain":["«صفحة الهبوط» هي صفحة واحدة بيوصل لها اللي يضغط على إعلانك. فيها عرضك وصور شغلك وأسعارك، وزر يفتح واتساب برسالة جاهزة. والموقع الكامل نفس الفكرة لكن بصفحات أكتر.","إحنا بنكتب المحتوى ونصمم الصفحة، ونربطها ببيكسل الإعلانات، وهو أداة قياس بتعرّفك مين ضغط على الإعلان ومين طلب. والدومين (عنوان الموقع) والاستضافة (المكان اللي الموقع محفوظ عليه) بيكونوا باسمك إنت، مش باسمنا."],"story":"شركة خدمات بتصرف على إعلانات، واللي بيضغط على الإعلان ما بيلاقي صفحة تشرح له العرض. مع صفحة الهبوط، بيوصل لصفحة سريعة على الموبايل فيها العرض والسعر، ويضغط زر واتساب فتتبعت رسالة جاهزة.","gains":[["إعلانك ما بيضيع","اللي يضغط على الإعلان بيوصل لصفحة سريعة ومريحة على الموبايل، فما يمشي."],["عارف نتيجة إعلانك","بنربطها ببيكسل الإعلانات، وهو أداة قياس بتعرف منها مين ضغط ومين طلب."],["كل شيء باسمك","الدومين (عنوان الموقع) والاستضافة باسمك، مش باسمنا."],["المحتوى علينا","بنكتب الكلام بالعربي ونصمم الصفحة، وإنت بتبعت لنا الشعار والصور والعرض."]],"qa":[["إيه الفرق بين الصفحة والموقع؟","الصفحة لعرض واحد أو إعلان واحد. الموقع بيعرّف بشغلك كله في أكتر من صفحة."],["أنا اللي هكتب المحتوى؟","لا. بنكتب المحتوى بالعربي ونصمم الصفحة، وإنت بتبعت لنا الشعار والصور والعرض."],["كم مدة التنفيذ؟","الصفحة من 3 لـ 7 أيام، والموقع من أسبوعين لثلاثة."],["فيه تكلفة بعد التسليم؟","حوالي 100 ج.م استضافة، ودومين بيتجدد كل سنة."],["إيه اللي يميزها عن باقي خدماتنا؟","دي أبسط وأسرع خدمة في قسم المواقع، ومعمولة عشان اللي بييجي من الإعلان يطلب. «موقع شركة مع مساعد ذكي» أكبر وفيه مساعد بيرد على الزوار، و«متجر إلكتروني ذكي» فيه سلة ودفع."]]},"company-site":{"sub":"موقع احترافي بيعرض خدماتك، وفيه مساعد بيرد على الزوار ويجمع لك المهتمين","problem":"لو موقعك قديم أو ما عندك موقع، والزائر ما بيلاقي إجابة سريعة، فبيمشي قبل ما يكلمك.","steps":["بنحدد الصفحات والرسالة الأساسية لشركتك","بنصمم الموقع ونكتب المحتوى بالعربي والإنجليزي","بنضيف المساعد الذكي ونربطه بواتساب والإيميل","بننشره على الدومين الخاص بك ونجهّزه للظهور في جوجل"],"plain":["موقع رسمي لشركتك بيعرض خدماتك وأعمالك السابقة، بالعربي والإنجليزي، وبتصميم معمول على هوية شركتك (شعارك وألوانك).","وفيه مساعد ذكي متدرّب على خدماتك: بيرد على الزائر، وياخد اسمه ورقمه ويبعتهم لك على واتساب والإيميل، بدل ما الزائر يتفرج ويمشي. وبنجهّز الموقع عشان يظهر للي بيدوّر على خدماتك في جوجل."],"story":"مكتب هندسي، وعميل بيدوّر عليه في جوجل قبل ما يكلمه. بيلاقي موقع مرتّب فيه الخدمات والمشاريع السابقة، يسأل المساعد سؤال وياخد الرد، ويترك رقمه. المكتب بيتصل به وهو عارف هو محتاج إيه.","gains":[["صورة محترمة قدام العميل","تصميم خاص بهوية شركتك، بيعطي ثقة قبل أول مكالمة."],["الزائر بيتحوّل لعميل مهتم","المساعد بيرد ويجمع الاسم والرقم ويبعتهم لك على واتساب والإيميل."],["اللي بيدوّر في جوجل يلاقيك","تجهيز أساسي للظهور في نتائج البحث، عشان موقعك يظهر للي بيدوّر على خدماتك."],["عارف مين بيزور موقعك","بنربط الموقع بأداة تحليل الزيارات، فتعرف كم واحد زاره."]],"qa":[["بيشمل كم صفحة؟","لحد 8 صفحات بلغتين: عربي وإنجليزي."],["الدومين باسمي؟","أيوه. بننشره على الدومين الخاص بك أو على اسم تختاره، وباسمك."],["مين بيكتب المحتوى؟","إحنا بنكتبه بالعربي والإنجليزي، من معلومات خدماتك وأعمالك السابقة."],["فيه تكلفة شهرية؟","حوالي 150 – 600 ج.م للاستضافة وتشغيل المساعد."],["إيه اللي يميزها عن باقي خدماتنا؟","ده موقع كامل ومعاه المساعد الذكي من أول يوم. «صفحة هبوط أو موقع يبيع» أبسط ومعمولة للإعلانات. ولو عندك موقع ومحتاج المساعد بس، شوف «مساعد ذكي على موقعك»."]]},"smart-store":{"sub":"متجر بياخد الطلب، يبعت الفاتورة، يأكد الشحن، ويقترح منتجات لكل عميل","problem":"لو بتبيع بالرسايل وبيدك: تسجيل الطلب والفاتورة والشحن والمتابعة، وكل ده بياخد وقت فريقك.","steps":["بنختار معاك المنصة المناسبة: Shopify أو سلة أو زد أو متجر خاص","بنرفع المنتجات ونصمم المتجر","بنربط الدفع والشحن ورسايل واتساب التلقائية","بنضيف اقتراحات المنتجات واسترجاع السلات المتروكة"],"plain":["متجر إلكتروني شغّال لوحده. العميل يطلب ويدفع، فتوصله الفاتورة ورسالة الشحن على واتساب من غير ما حد من فريقك يكتب شيء.","وبعدها المتجر بيقترح على كل عميل منتجات تناسب اللي اشتراه، وبيبعت رسالة للي ترك السلة من غير ما يدفع. إحنا بنختار معاك المنصة (البرنامج اللي المتجر مبني عليه)، ونرفع لحد 100 منتج، ونربط الدفع والشحن."],"story":"براند بيبيع من الرسايل: حد يرد، حد يسجّل الطلب، حد يكتب الفاتورة، وحد يتابع الشحن. مع المتجر، العميل بيطلب ويدفع لوحده، والفاتورة ورسالة الشحن بيوصلوه، والفريق بيركّز في تجهيز الطلبات.","gains":[["بيع من غير رسايل يدوية","لا تسجيل طلبات ولا كتابة فواتير ولا متابعة شحن من فريقك."],["كل طلب موثّق","فاتورة ورسالة شحن لكل طلب، بيوصلوا العميل لوحدهم."],["مبيعات زيادة","اقتراحات منتجات لكل عميل، ورسايل ترجّع اللي ترك السلة."],["المنصة اللي تناسبك","بنختار معاك: Shopify أو سلة أو زد أو متجر خاص."]],"qa":[["المتجر بيتبني على أي منصة؟","بنختار معاك الأنسب: Shopify أو سلة أو زد أو متجر خاص."],["بترفعوا كم منتج؟","لحد 100 منتج ضمن الخدمة، مع ربط الدفع والشحن."],["كم التكلفة الشهرية؟","اشتراك المنصة، ومعه حوالي 300 – 1,000 ج.م تشغيل."],["محتاجين مني إيه؟","صور المنتجات وأسعارها، وحسابك عند شركة الدفع الإلكتروني وشركة الشحن، وسياسة الاستبدال والاسترجاع."],["إيه اللي يميزها عن باقي خدماتنا؟","ده متجر كامل على الإنترنت فيه سلة ودفع وشحن. لو عندك متجر شغّال ومحتاج إضافة واحدة بس، شوف «تأكيد طلبات الدفع عند الاستلام» أو «استرجاع السلات المتروكة». ولو محتاج تطبيق موبايل للطلبات، شوف «تطبيق متجر وطلبات»."]]},"dashboard":{"sub":"نظام ويب تدير منه شغلك اليومي، ومعاه تقارير وملخصات ذكية بتتكتب لوحدها","problem":"لو شغل شركتك ماشي على جداول متفرقة ورسايل واتساب، وما في صورة واضحة للي بيحصل كل يوم.","steps":["بنجلس مع فريقك ونرسم طريقة الشغل الحالية","بنصمم الشاشات، ونحدد كل موظف يشوف إيه","بنبني النظام ونربطه ببياناتك الحالية","بنضيف تقارير وملخصات بيكتبها الذكاء الاصطناعي لوحده"],"plain":["«لوحة التحكم» هي نظام بتفتحه من المتصفح، وبيجمع شغلك اليومي في شاشة واحدة، بدل الجداول المتفرقة ورسايل واتساب.","الذكاء الاصطناعي بيكتب لك ملخص باللي حصل، وتقدر تسأله سؤال فيجاوبك من بياناتك. كل موظف بيشوف بس الشاشات اللي تخص شغله، وإحنا بندرّب الفريق على النظام."],"story":"شركة توزيع عندها أكتر من فرع، وكل فرع بيبعت أرقامه في جدول لوحده على واتساب، والمدير بيجمعهم بيده. مع النظام، بيفتح شاشة واحدة يلاقي اللي انباع، واللي قرّب يخلص، وأي فرع مبيعاته أعلى، من غير ما يطلب تقرير من حد.","gains":[["صورة واضحة كل يوم","بتعرف إيه اللي انباع، وإيه اللي قرّب يخلص، وأي فرع مبيعاته أعلى، من غير ما تطلب تقرير من حد."],["كل موظف شايف اللي يخصه","كل وظيفة في الشركة لها شاشاتها، وما حد بيشوف اللي ما يخصه."],["مش هتبدأ من الصفر","بنربط النظام بجداولك وأنظمتك الحالية."],["الفريق بيتدرّب عليه","تدريب الفريق على النظام جزء من الخدمة."]],"qa":[["بتدرّبوا الفريق عليه؟","أيوه، تدريب الفريق جزء من الخدمة."],["بتعرفوا احتياجنا إزاي؟","بنجلس مع فريقك أولًا ونرسم طريقة الشغل الحالية، وبعدها نصمم الشاشات عليها."],["كم مدة التنفيذ؟","من 4 لـ 8 أسابيع."],["فيه تكلفة شهرية؟","حوالي 500 – 2,500 ج.م استضافة وصيانة."],["إيه اللي يميزها عن باقي خدماتنا؟","ده نظام بيتفصّل على طريقة شغل شركتك. «نظام إدارة العملاء (CRM)» متخصص في العملاء والمبيعات بس، و«تطبيق داخلي للشركة» هو تطبيق موبايل لمهام الموظفين وحضورهم وطلباتهم."]]},"booking-app":{"sub":"تطبيق لعملاءك يحجزوا منه ويدفعوا، ومعاه مساعد بيرد على أسئلتهم","problem":"لو الحجز عندك بالتليفون والرسايل ومتعب لفريقك، وعملاءك حابين تطبيق يشوفوا فيه المواعيد ويحجزوا منه مباشرة.","steps":["بنحدد الشاشات: الخدمات، المواعيد، الحجز، الدفع، الحساب","بنصمم شكل التطبيق بهويتك ونراجعه معاك","بنبني التطبيق لـ Android وiOS، ومعاه لوحة إدارة لك","بننشره على متاجر التطبيقات ونتابع معاك أول شهر"],"plain":["تطبيق باسم شغلك على Android وiPhone. عميلك يفتحه، يشوف الخدمات والمواعيد المتاحة، يحجز ويدفع، ويوصله تذكير قبل الموعد.","وفيه مساعد ذكي بيرد على أسئلة العميل. وإنت عندك لوحة إدارة بتشوف منها كل الحجوزات. وإحنا اللي بننشر التطبيق على Google Play وApp Store، على حسابات باسمك إنت."],"story":"نادي رياضي (جيم)، والأعضاء بيتصلوا يسألوا عن مواعيد التمارين، وموظف الاستقبال مش قادر يلحق على الكل. مع التطبيق، العضو يفتح الموبايل، يشوف المواعيد المتاحة، يحجز ويدفع، ويوصله تذكير. وموظف الاستقبال يتفرغ للي واقف قدامه.","gains":[["حجز من غير مكالمات","العميل بيحجز لوحده في أي وقت، وفريقك مش مربوط بالتليفون طول اليوم."],["اسمك على موبايل عميلك","تطبيقك موجود عنده دايمًا، فيرجع لك بدل ما يدوّر على غيرك."],["كل الحجوزات قدامك","لوحة إدارة للحجوزات، مع إشعارات وتذكيرات بتتبعت لوحدها."],["الدفع من التطبيق","العميل بيدفع إلكتروني وهو بيحجز."]],"qa":[["مين بينشر التطبيق على المتاجر؟","إحنا بننشره، على حسابات المطوّر في Google Play وApp Store باسمك إنت."],["العميل بيدفع من التطبيق؟","أيوه، فيه دفع إلكتروني."],["كم مدة التنفيذ؟","من 6 لـ 10 أسابيع، وبنتابع معاك أول شهر بعد النشر."],["فيه تكلفة شهرية؟","حوالي 800 – 2,500 ج.م لتشغيل التطبيق على الإنترنت (سيرفرات) والصيانة."],["إيه اللي يميزها عن باقي خدماتنا؟","ده تطبيق كامل باسمك على موبايل العميل، وفيه دفع إلكتروني. «مساعد واتساب للرد والحجز» بيحجز من محادثة واتساب من غير تطبيق، وهو أسرع في التنفيذ وأقل في التكلفة."]]},"ordering-app":{"sub":"تطبيق طلبات لمطعمك أو متجرك، بيقترح على كل عميل اللي يناسبه","problem":"لو بتدفع عمولة كبيرة لتطبيقات التوصيل، وما عندك بيانات عملاءك ولا طريقة تكلمهم بها.","steps":["بنحدد المنيو أو قائمة المنتجات ومناطق التوصيل","بنصمم طريقة طلب سريعة وسهلة","بنبني التطبيق ولوحة الطلبات للمطبخ أو المخزن","بنضيف الاقتراحات الذكية والعروض الخاصة"],"plain":["تطبيق طلبات خاص بمطعمك أو متجرك إنت، بدل ما تعتمد على تطبيقات التوصيل. العميل بيطلب منه مباشرة، والتطبيق بيتذكّر طلبه المعتاد ويقترح عليه اللي يناسبه.","الطلب بيوصل على لوحة في المطبخ أو المخزن، والدفع إلكتروني أو كاش. وبيانات عملاءك بتكون عندك: عارف مين بيطلب وبيطلب إيه، وتبعت له عروضك ونقاط الولاء (نقاط بياخدها العميل كل ما يطلب)."],"story":"مطعم كل طلباته جاية من تطبيقات التوصيل، بيدفع عمولة على كل طلب، وما يعرف يكلم عملاءه. مع تطبيقه، العميل اللي بيطلب دايمًا يلاقي زر «اطلب تاني» وعرض معمول له، والطلب يوصل المطبخ مباشرة.","gains":[["الطلب بيوصلك مباشرة","العميل بيطلب من تطبيقك إنت، مش من تطبيق بياخد عمولة على كل طلب."],["بيانات عملاءك عندك","عارف مين بيطلب وبيطلب إيه، وتكلمه بعروضك."],["عملاء بيرجعوا","نقاط ولاء وعروض خاصة وزر «اطلب تاني»."],["المطبخ شايف كل طلب","لوحة طلبات للمطبخ أو المخزن، ومعاها إدارة المنيو."]],"qa":[["بيقبل الدفع كاش؟","أيوه، فيه دفع إلكتروني وكاش."],["الطلبات بتوصل المطبخ إزاي؟","على لوحة طلبات للمطبخ أو المخزن، ومعاها إدارة المنيو."],["كم مدة التنفيذ؟","من 8 لـ 12 أسبوع."],["محتاجين مني إيه؟","المنيو أو قائمة المنتجات بالأسعار والصور، ومناطق التوصيل وتكلفتها، وحسابات المطوّر على متاجر التطبيقات."],["إيه اللي يميزها عن باقي خدماتنا؟","ده تطبيق موبايل للطلبات، ومعاه نقاط ولاء وزر «اطلب تاني». «متجر إلكتروني ذكي» بيبيع من موقع على الإنترنت، و«تطبيق حجز ذكي» للمواعيد مش للطلبات."]]},"team-app":{"sub":"تطبيق لفريقك: مهام، حضور، طلبات، ومساعد بيجاوب من ملفات الشركة","problem":"لو فريقك بيتواصل في جروبات واتساب متفرقة، والمهام والطلبات بتضيع، والموظف الجديد بيسأل نفس الأسئلة كل مرة.","steps":["بنحدد الفريق محتاج إيه كل يوم: مهام، حضور، طلبات، تقارير","بنصمم الشاشات على حسب وظيفة كل موظف","بنبني التطبيق ولوحة الإدارة","بنضيف مساعد بيجاوب من سياسات وملفات الشركة"],"plain":["تطبيق لموظفيك بدل جروبات واتساب المتفرقة. فيه المهام، والحضور، والطلبات زي الإجازات، وكل شيء له مكان وصاحب وحالة.","وفيه مساعد بيجاوب الموظف من سياسات وملفات الشركة، فالموظف الجديد ما يسأل زملاءه نفس الأسئلة كل مرة. والمدير بيوصله تنبيه بالطلبات الجديدة وتقرير كل أسبوع."],"story":"محمود حابب يعرف سياسة الإجازات المرضية. بدل ما يسأل في الجروب، بيسأل المساعد في التطبيق وياخد الإجابة من ملفات الشركة، ويقدّم طلب الإجازة من نفس التطبيق. والمدير بيوصله تنبيه بالطلب.","gains":[["ما في مهمة بتضيع","كل مهمة وكل طلب له مكان وصاحب وحالة."],["الموظف الجديد بيلاقي الإجابة","بيسأل المساعد عن أي سياسة، بدل ما يكرر نفس الأسئلة على زملاءه."],["المدير شايف الصورة","تنبيهات بالطلبات الجديدة وتقارير أسبوعية."],["شاشات على حسب الوظيفة","كل موظف بيشوف اللي يخص شغله، والإدارة لها لوحة خاصة."]],"qa":[["بيتربط بالأنظمة اللي عندنا؟","أيوه، بنربطه بالأنظمة اللي شغّالين عليها."],["كل الموظفين هيشوفوا نفس الشاشات؟","لا. الشاشات بتتصمم على حسب وظيفة كل موظف، والإدارة لها لوحة خاصة."],["المساعد بيجاوب إزاي؟","من سياسات وملفات الشركة اللي بتبعتوها لنا."],["كم مدة التنفيذ؟","من 6 لـ 10 أسابيع."],["إيه اللي يميزها عن باقي خدماتنا؟","ده تطبيق موبايل لموظفيك مش لعملاءك: مهام وحضور وطلبات. «لوحة تحكم ونظام ويب داخلي» بتشتغل من المتصفح، ومعمولة لمتابعة أرقام الشغل والتقارير."]]},"app-mvp":{"sub":"بنحوّل فكرة تطبيقك المعتمد على الذكاء الاصطناعي لنسخة أولى جاهزة للتجربة والعرض على المستثمرين","problem":"لو عندك فكرة تطبيق وما تعرف تبدأ من فين، وبناء كل شيء مرة واحدة غالي وفيه مخاطرة.","steps":["جلسة نحدد فيها أهم ميزة لازم تشتغل في النسخة الأولى","نماذج شاشات تفاعلية تجرّب بها الفكرة قبل البرمجة","نبني النسخة الأولى بالميزات الأساسية بس","إطلاق تجريبي مع مستخدمين حقيقيين وقياس النتائج"],"plain":["MVP يعني نسخة أولى صغيرة من تطبيقك، فيها أهم ميزة بس. بتتبني بسرعة وبتكلفة أقل من التطبيق الكامل.","الفكرة إنك تجرّبها مع مستخدمين حقيقيين وتعرضها على المستثمرين قبل ما تصرف على الباقي. بنبدأ بجلسة نحدد فيها أهم ميزة، وبعدها نماذج شاشات تجرّب بها الفكرة قبل ما نبدأ البرمجة. والكود (ملفات برمجة التطبيق) في النهاية بيكون باسمك."],"story":"واحد عنده فكرة تطبيق، وخايف يصرف عليها وبعدها يكتشف إن الناس مش محتاجاه. بيبدأ بنسخة فيها الميزة الأساسية بس: أول أسبوعين نماذج شاشات، وبعدها بناء الميزة، وبعدها إطلاق تجريبي لـ 50 مستخدم وتقرير بالنتائج. وقتها بيقرر الخطوة اللي بعدها وهو شايف نتائج حقيقية.","gains":[["بتختبر الفكرة قبل المخاطرة","بتعرف الناس محتاجة تطبيقك فعلًا ولا لا، قبل ما تبني كل شيء."],["شيء حقيقي تعرضه","تطبيق شغّال قدام المستثمر أقوى من عرض على ورق."],["الكود ملكك","ملفات برمجة التطبيق باسمك، وتكمّل عليها مع أي فريق."],["بتشوف الشكل قبل البرمجة","نماذج شاشات تفاعلية تجرّب بها الفكرة قبل ما نبدأ نبني."]],"qa":[["فكرتي لسه مش واضحة، أبدأ؟","بنبدأ بجلسة نحدد فيها أهم ميزة لازم تشتغل في النسخة الأولى، وبعدها نماذج شاشات تجرّب بها الفكرة قبل البرمجة."],["وبعد النسخة الأولى؟","إطلاق تجريبي مع مستخدمين حقيقيين وقياس النتائج، وعلى أساسها بتقرر الخطوة اللي بعدها."],["كم مدة التنفيذ؟","من 6 لـ 12 أسبوع."],["محتاجين مني إيه؟","وصف الفكرة والعميل اللي بتستهدفه، وأمثلة لتطبيقات شبهها، وميزانية وموعد مستهدف."],["إيه اللي يميزها عن باقي خدماتنا؟","دي لفكرة جديدة لسه بتتجرّب: بنبني أهم ميزة بس عشان تختبرها. باقي خدمات التطبيقات بتبني تطبيق كامل لشغل قائم: حجز، أو طلبات، أو تطبيق للموظفين."]]}};
S.forEach(s => { const m = MORE[s.id]; ['sub','problem','steps'].forEach(k => { if (m && m[k]) s[k] = m[k]; }); });
const F = (id, label, value, opt) => Object.assign({id, label, value}, opt || {});
