const sid = p => p + '-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
async function call(path, data){
  if (data && data.demo) track('demo_used', {service: path});
  const r = await fetch(API + path, {method:'POST', body:new URLSearchParams(data)});
  if (!r.ok) throw new Error('HTTP ' + r.status);
  return r.json();
}
function bubbles(box, list, onQuick){
  list.forEach(([t, x]) => {
    if (t === 'q') {
      const row = el('div',{class:'qr'});
      String(x).split('|').forEach(label => {
        const b = el('button',{type:'button',text:label});
        if (onQuick) b.onclick = () => { row.querySelectorAll('button').forEach(k => { k.disabled = true; }); onQuick(label); };
        else b.disabled = true;
        row.append(b);
      });
      box.append(row);
    } else if (x) box.append(el('div',{class:'b ' + t, text:String(x)}));
  });
  box.scrollTop = box.scrollHeight;
}
function fileToDataUrl(file, max){
  return new Promise((ok, bad) => {
    const img = new Image(), url = URL.createObjectURL(file);
    img.onload = () => {
      const k = Math.min(1, max / Math.max(img.width, img.height));
      const c = document.createElement('canvas'); c.width = Math.round(img.width * k); c.height = Math.round(img.height * k);
      c.getContext('2d').drawImage(img, 0, 0, c.width, c.height); URL.revokeObjectURL(url); ok(c.toDataURL('image/jpeg', .85));
    };
    img.onerror = () => { URL.revokeObjectURL(url); bad(new Error('image')); };
    img.src = url;
  });
}
function chatUi(box, path, opts){
  const session = opts.session || sid(path); let busy = false, first = true;
  const input = el('input',{autocomplete:'off',placeholder:opts.ph || 'اكتب رسالتك...','aria-label':'رسالتك'});
  const send = el('button',{class:'btn pri',type:'submit',text:'إرسال'});
  const form = el('form',{class:'chatin'}, input, send);
  if (opts.hello) bubbles(box, [['r', opts.hello]]);
  form.addEventListener('submit', async e => {
    e.preventDefault();
    const text = input.value.trim(); if (!text || busy) return;
    busy = true; send.disabled = true; input.value = '';
    bubbles(box, [['c', text]]);
    const wait = el('div',{class:'typing',text:'… بيكتب'}); box.append(wait); box.scrollTop = box.scrollHeight;
    try {
      const res = await call(path, Object.assign({sessionId:session, message:(first && opts.context ? opts.context + ' ' : '') + text, channel:'site'}, opts.live ? {} : {demo:'1'}));
      first = false; wait.remove(); bubbles(box, [['r', res.reply || 'الرد ما وصل. جرّب مرة تانية.']]);
    } catch (err) {
      wait.remove(); bubbles(box, [['n', 'مش قادرين نوصل للمساعد الآن. جرّب بعد شوية، أو ابعت لنا من صفحة التواصل.']]);
    }
    busy = false; send.disabled = false; input.focus();
  });
  return form;
}
function liveDemo(s){
  const d = DEMOS[s.id]; if (!d) return null;
  const box = el('div',{class:'chat','aria-live':'polite','aria-label':'نتيجة التجربة'});
  const left = el('div',{class:'dform'}, el('span',{class:'livetag'}, el('i'), document.createTextNode('تجربة حية · شغّالة الآن')), el('h3',{text:'جرّب الخدمة بنفسك'}), el('p',{class:'muted',text:d.intro}));
  const wrap = el('section',{class:'demo','aria-label':'تجربة حية للخدمة'}, left, box);
  if (d.kind === 'link') {
    left.append(el('a',{class:'btn pri',href:d.url,target:'_blank',rel:'noopener',text:d.cta}));
    bubbles(box, s.ex.filter(m => m[0] !== 'q'));
    return wrap;
  }
  if (d.kind === 'chat') { left.append(chatUi(box, d.path, d)); return wrap; }
  let busy = false, last = null;
  const btn = el('button',{class:'btn pri',type:'submit',text:d.cta});
  const run = async (data, fresh) => {
    if (busy) return; busy = true; btn.disabled = true;
    if (fresh) box.textContent = '';
    const wait = el('div',{class:'typing',text:'… لحظة واحدة'}); box.append(wait); box.scrollTop = box.scrollHeight;
    try {
      const res = await call(d.path, Object.assign({demo:'1'}, d.extra, data));
      wait.remove(); if (fresh) last = res;
      bubbles(box, res.messages || [], d.quick ? onQuick : null);
      if (fresh && replyRow) replyRow.hidden = false;
      if (fresh) box.scrollIntoView({block:'nearest', behavior:'smooth'});
    } catch (err) {
      wait.remove(); bubbles(box, [['n', 'مش قادرين نوصل للخدمة الآن. جرّب بعد شوية، أو اطلب تشوفها شغّالة في الاستشارة المجانية.']]);
    }
    busy = false; btn.disabled = false;
  };
  const onQuick = label => { const data = d.quick(label, last || {}); if (data) run(data, false); else bubbles(box, [['c', label], ['n', d.quickNote]]); };
  const form = el('form',{class:'dform'});
  let fileIn = null, replyRow = null;
  if (d.kind === 'file') {
    fileIn = el('input',{id:'demo-file',type:'file',accept:'image/*'});
    form.append(el('div',{class:'fld'}, el('label',{for:'demo-file',text:'صورة الفاتورة'}), fileIn));
  } else d.fields.forEach(f => {
    const id = 'demo-' + f.id; let c;
    if (f.options) { c = el('select',{id}); f.options.forEach(o => c.append(el('option',{value:o,text:o}))); }
    else if (f.area) c = el('textarea',{id});
    else c = el('input',{id,type:f.type || 'text'});
    c.value = f.value; c.dataset.k = f.id;
    form.append(el('div',{class:'fld'}, el('label',{for:id,text:f.label}), c));
  });
  form.append(btn);
  form.addEventListener('submit', async e => {
    e.preventDefault();
    if (fileIn) {
      const file = fileIn.files[0];
      if (!file) { box.textContent = ''; bubbles(box, [['n', 'اختار صورة فاتورة أولًا.']]); return; }
      let image;
      try { image = await fileToDataUrl(file, 1500); } catch (err) { box.textContent = ''; bubbles(box, [['n', 'ما قدرنا نقرا الصورة دي. جرّب صورة JPG أو PNG.']]); return; }
      run({image}, true); return;
    }
    const data = {}; form.querySelectorAll('[data-k]').forEach(c => { data[c.dataset.k] = c.value.trim(); });
    run(data, true);
  });
  left.append(form);
  if (d.second) { const b2 = el('button',{class:'btn sec',type:'button',text:d.second.label}); b2.onclick = () => run(d.second.data, true); left.append(b2); }
  if (d.reply) {
    const rin = el('input',{autocomplete:'off',placeholder:d.reply,'aria-label':'رد العميل'});
    replyRow = el('form',{class:'chatin'}, rin, el('button',{class:'btn sec',type:'submit',text:'ردّ'}));
    replyRow.hidden = true;
    replyRow.addEventListener('submit', e => { e.preventDefault(); const t = rin.value.trim(); if (!t) return; rin.value = ''; onQuick(t); });
    left.append(replyRow);
  }
  bubbles(box, [['n', 'النتيجة هتظهر هنا. البيانات تجريبية وما بتتبعت لأي رقم حقيقي.']]);
  return wrap;
}

